#include "Bosses/DreamEthanBossCharacter.h"
#include "Components/HealthComponent.h"
ADreamEthanBossCharacter::ADreamEthanBossCharacter(){BossId=TEXT("boss.dream_ethan");MissionId=TEXT("Main.C09.03.DreamFight");OutcomeKey=TEXT("DreamEthan.Outcome");OutcomeValue=TEXT("Accepted");bCompleteMissionOnDefeat=true;AttackCooldown=1.25f;AggroRange=1850.f;AttackRange=225.f;AttackDamage=18.f;AttackStaminaDamage=30.f;}
void ADreamEthanBossCharacter::BeginPlay(){Super::BeginPlay();if(Health){Health->MaxHealth=360.f;Health->CurrentHealth=360.f;Health->OnHealthChanged.AddDynamic(this,&ADreamEthanBossCharacter::HandleDreamHealthChanged);}ApplyDreamPhase(1);}
void ADreamEthanBossCharacter::HandleDreamHealthChanged(float NewHealth,float MaximumHealth,float Delta){if(Delta>=0.f)return;const float Fraction=NewHealth/FMath::Max(1.f,MaximumHealth);if(Fraction<=PhaseThreeHealthFraction)ApplyDreamPhase(3);else if(Fraction<=PhaseTwoHealthFraction)ApplyDreamPhase(2);}
void ADreamEthanBossCharacter::ApplyDreamPhase(int32 NewPhase){if(NewPhase<=DreamPhase&&NewPhase!=1)return;DreamPhase=FMath::Clamp(NewPhase,1,3);if(DreamPhase==1){AttackCooldown=1.25f;AttackDamage=18.f;AttackStaminaDamage=30.f;}else if(DreamPhase==2){AttackCooldown=.92f;AttackDamage=21.f;AttackStaminaDamage=38.f;}else{AttackCooldown=.70f;AttackDamage=24.f;AttackStaminaDamage=46.f;AggroRange=2200.f;}}
